{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "In pigs, [11C](R)-16 entered the brain after IV injection with a peak SUV of ~2.5 g/mL, demonstrating direct BBB permeability in a close analog.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "In rats, [11C]4 rapidly entered the brain after injection, reaching ~1.2 SUV at 3–5 min, supporting meaningful CNS access for a closely related analog.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "In rats, [11C]6 showed low whole-brain uptake (0.189 %ID/g at 5 min) and was increased by cyclosporin A, indicating efflux-limited brain penetration in a moderately similar analog.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most direct in-vivo evidence shows clear brain entry after IV administration, and most similar analogs are BBB-permeable. One moderately similar analog is efflux-limited with low brain uptake, but the overall transferred evidence supports meaningful CNS access.",
  "evidence_gaps": [
    "No direct experimental record for the query molecule; all evidence is from analogs with Morgan similarity 0.35–0.45.",
    "A moderately similar analog is a P-gp/ABC efflux substrate with low baseline brain uptake, so efflux liability cannot be fully excluded for the query.",
    "Cross-species and radiotracer-specific differences (pig, rat, mouse, monkey) limit quantitative transfer."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

